import { createWriteStream } from 'node:fs';
import { mkdtemp, rm, stat } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path, { basename, dirname, join } from 'node:path';
import { pipeline } from 'node:stream/promises';
import { createGzip } from 'node:zlib';
import { buildStudio, compareDependencyVersions } from '@sanity/cli-build/_internal/build';
import { pack } from 'tar-fs';
export async function prepareStudioAsset({ blueprintFileDir, resource, }) {
    // validate resource has an externalId
    if (!('externalId' in resource) ||
        typeof resource.externalId !== 'string' ||
        !resource.externalId) {
        return {
            success: false,
            async cleanup() {
                // no op
            },
            error: `Unable to determine appId for sanity.studio resource '${resource.name}'`,
        };
    }
    let cleanup = async () => {
        // no op
    };
    const studioPath = path.resolve(blueprintFileDir, resource.src);
    try {
        const studioPathStat = await stat(studioPath);
        if (!studioPathStat.isDirectory()) {
            return {
                success: false,
                cleanup,
                error: `Property 'src' on resource with type '${resource.type}' must be a directory`,
            };
        }
    }
    catch (error) {
        const msg = error instanceof Error ? error.message : String(error);
        return {
            success: false,
            cleanup,
            error: `Unable to read given 'src' on resource with type '${resource.type}': ${msg}`,
        };
    }
    try {
        const outDir = await mkdtemp(join(tmpdir(), `studio-build-`));
        const outFile = `${outDir}.tar.gz`;
        cleanup = async () => {
            await rm(outDir, { force: true, recursive: true });
            await rm(outFile, { force: true });
        };
        const appId = resource.externalId;
        try {
            await buildStudio({
                appId,
                autoUpdatesEnabled: resource.autoUpdates.enabled,
                checkAppId() { },
                async compareDependencyVersions(packages) {
                    return compareDependencyVersions(packages, studioPath, { appId });
                },
                determineBasePath() {
                    return resource.basePath ?? '/';
                },
                isApp: false,
                isWorkbenchApp: false,
                minify: resource.minify ?? true,
                outDir,
                output: createSilentOutput(),
                reactCompiler: resource.reactCompiler || false,
                schemaExtraction: undefined,
                sourceMap: resource.sourceMap ?? false,
                stats: false,
                unattendedMode: true,
                // TODO pass in vite config from the studio resource
                vite: undefined,
                workDir: studioPath,
                eventListener: {
                    onBuildFail({ message }) {
                        throw new Error(message);
                    },
                    onInvalidStyledComponentsVersionRange({ message }) {
                        throw new Error(message);
                    },
                    onNoDeclaredStyledComponentsVersion({ message }) {
                        throw new Error(message);
                    },
                    onNoInstalledSanityVersion({ message }) {
                        throw new Error(message);
                    },
                    onNoInstalledStyledComponentsVersion({ message }) {
                        throw new Error(message);
                    },
                    onPreReleaseInNonInteractiveAutoUpdate({ message }) {
                        throw new Error(message);
                    },
                },
            });
        }
        catch (error) {
            const message = error instanceof Error ? error.message : String(error);
            return {
                success: false,
                cleanup,
                error: message,
            };
        }
        // tar/gzip/write the built output
        await pipeline(pack(dirname(outDir), { entries: [basename(outDir)] }), createGzip(), createWriteStream(outFile));
        return {
            success: true,
            cleanup,
            // studio must be pre built (e.g. with `npm run build`) and tarred/gzipped
            outputPath: outFile,
        };
    }
    catch (error) {
        return {
            success: false,
            cleanup,
            error: error instanceof Error ? error.message : String(error),
        };
    }
}
function createSilentOutput() {
    return {
        error(input, options) {
            if (typeof options?.exit === 'number') {
                if (input instanceof Error) {
                    throw input;
                }
                throw new Error(input);
            }
            return undefined;
        },
        log() { },
        warn(input) {
            return input;
        },
    };
}
